140→export default function NormativaIndex({ regulations }: Props) {
141→    const [filter, setFilter] = useState<Filter>('all');
142→
143→    const filtered = regulations.filter((r) => {
144→        if (filter === 'pending') return !r.is_resolved;
145→        if (filter === 'resolved') return r.is_resolved;
146→        return true;
147→    });
148→
149→    const urgentCount = regulations.filter((r) => r.severity === 'urgent' && !r.is_resolved).length;
150→    const warningCount = regulations.filter((r) => r.severity === 'warning' && !r.is_resolved).length;
151→    const infoCount = regulations.filter((r) => r.severity === 'info' && !r.is_resolved).length;
152→
153→    const filters: { key: Filter; label: string }[] = [
154→        { key: 'all', label: 'Todas' },
155→        { key: 'pending', label: 'Pendientes' },
156→        { key: 'resolved', label: 'Resueltas' },
157→    ];
158→
159→    return (
