168→                            {urgentCount} urgente{urgentCount > 1 ? 's' : ''}
169→                        </span>
170→                    )}
171→                    {warningCount > 0 && (
172→                        <span className="inline-flex items-center gap-1 bg-[#FFF3E0] px-2 py-1 text-xs font-bold text-[#E65100]">
