177→                        <span className="inline-flex items-center gap-1 bg-[#E3F2FD] px-2 py-1 text-xs font-bold text-[#1565C0]">
178→                            {infoCount} info
179→                        </span>
180→                    )}
181→                </div>
182→
183→                <div className="flex gap-0 border-2 border-black">
184→                    {filters.map((f) => (
185→                        <button
186→                            key={f.key}
187→                            onClick={() => setFilter(f.key)}
